(()=>{'use strict';const $=id=>document.getElementById(id);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const scenes=[...document.querySelectorAll('.scene')];const dots=[...document.querySelectorAll('.section-dots a')];if('IntersectionObserver'in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');dots.forEach(d=>d.classList.toggle('active',d.hash==='#'+e.target.id));}}),{threshold:.2});scenes.forEach(s=>observer.observe(s));}let ticking=false;function onScroll(){if(ticking)return;ticking=true;requestAnimationFrame(()=>{document.querySelector('.nav').classList.toggle('scrolled',scrollY>50);if(!reduced&&innerWidth>760){for(const s of scenes){const img=s.querySelector('.scene-image');const r=s.getBoundingClientRect();if(img&&r.bottom>0&&r.top<innerHeight)img.style.transform=`scale(1.04) translateY(${r.top*-.065}px)`;}}ticking=false;});}addEventListener('scroll',onScroll,{passive:true});onScroll();$('menu-toggle').onclick=()=>{const nav=document.querySelector('.nav nav');const open=nav.classList.toggle('open');$('menu-toggle').setAttribute('aria-expanded',String(open));};document.querySelectorAll('.nav nav a').forEach(a=>a.onclick=()=>{document.querySelector('.nav nav').classList.remove('open');$('menu-toggle').setAttribute('aria-expanded','false');});
const stages=['Variables, control flow, functions, collections and debugging. Start from scratch with worked examples and small challenges.','Big-O reasoning, binary search, two pointers, sliding windows, hashing, sorting and stacks. Learn why each pattern works.','Linked lists, recursion, backtracking, trees, heaps, tries and graphs. Turn abstract structures into practical solutions.','Greedy algorithms, dynamic programming, practical Python engineering and timed mock practice. Explain your approach and test the edges.'];document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-stage]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('stage-detail').textContent=stages[Number(b.dataset.stage)];});let step=0;const trace=['i=0 · value=2 · remember 2 → index 0','i=1 · value=7 · complement 2 is in seen','Return [0, 1] · 2 + 7 = 9 ✓','[2, 7, 11, 15] · target 9'];$('demo-run').onclick=()=>{$('demo-result').textContent=trace[step++%trace.length];};
const answers=[
{keys:['get started','start','begin','beginner','scratch','experience','first','how to use'],text:'Start with Enter CodeTrail and sign in to access the learning workspace. Choose Python, then the first Foundations lesson. Read the explanation, try an exercise, run its tests and check your understanding. Sign in to keep progress across visits. The course starts from scratch.'},
{keys:['save','saved','saving','progress','cloud','retrieve','refresh','browser memory','storage','draft','device','sync','account specific'],text:'Sign in to load your own cloud progress and code drafts. Changes save automatically after a short pause. Wait for “Saved to your account” before leaving. Each account has separate progress. Saved items include lessons, language, quizzes, solved exercises and drafts; AI chats can be saved through optional account memory; mock timers are not saved. If saving fails, keep the tab open and use Retry sync.'},
{keys:['login','log in','sign in','google','account','register','signup','sign up','password'],text:'Choose Log in to use Sign in with ChatGPT. “Continue with Google” is available within the OpenAI login flow; it still uses an OpenAI account. After login, you return to the learning workspace. Always use the same account to retrieve your progress.'},
{keys:['ai','tutor','artificial intelligence','model','download','webgpu','gpu','key','fees','cost','price','free'],text:'The optional coding tutor runs a small AI model on your device. Enable it in the workspace to explain topics, review code or suggest fixes. Its first download is about 1 GB and needs a WebGPU-capable browser with roughly 2 GB of graphics memory. No API key or AI API fee is required. Model files come from public hosts; generation runs locally; optional account memory saves chat questions and answers. AI can make mistakes.'},
{keys:['fix','correct','syntax','mistake','error','undo','edit code'],text:'In the workspace, open the AI tutor and choose Explain error, Review my code or Fix my code. A complete correction can be applied to the editor when you explicitly ask it to fix or modify your code. Other code suggestions have an Apply button. It does not execute the code automatically. Undo is available for an applied fix. Check every change and run tests yourself. The model must load successfully on a compatible device.'},
{keys:['python','run','execute','test','tests','compiler','pyodide'],text:'Python runs locally in your browser using Pyodide. Choose a challenge, edit its solve function and select Run tests. The result shows how your code behaved on the supplied cases. Passing those tests is useful feedback, but does not prove correctness for every possible input.'},
{keys:['java','javac'],text:'CodeTrail includes a Java basics track with explanations, an editor and code downloads. Java is not compiled or executed here. Use a local Java development environment to run downloaded code. The expanded 48-lesson course and browser test runner focus on Python.'},
{keys:['course','curriculum','modules','lesson','topics','data structures','algorithms','dsa','learn','syllabus'],text:'The Python course has 16 modules, 48 written lessons and 96 original coding exercises. It covers foundations, collections, Big-O, search, sorting, common patterns, linked lists, recursion, trees, heaps, tries, graphs, greedy algorithms, dynamic programming, Python engineering and interview practice. Each lesson includes worked examples and exercises.'},
{keys:['meta','microsoft','interview','professional','job','guarantee','ready','certificate','certification'],text:'The course supports interview preparation through algorithm patterns, reasoning, complexity analysis, testing and mock practice. It is independent of Meta and Microsoft. Finishing it does not guarantee professional proficiency, certification or a job. Experienced roles may also assess system design and behavioral experience; confirm your interview format with your recruiter.'},
{keys:['mock','timer','timed','assessment','no run'],text:'Timed mock practice helps you rehearse reasoning under time pressure. No-run mocks hide hints, solutions and execution and pause AI assistance. Their durations are course practice targets, not promised company interview formats. Mock timers are not saved across reloads.'},
{keys:['hint','solution','answer','stuck','quiz','exercises','problems','challenge'],text:'Each Python lesson has two coding exercises with a solve-function contract, starter code, three progressive hints, test cases, a worked solution and complexity notes. There is also a concept quiz. Try independently before revealing help, and revisit a fresh variation later.'},
{keys:['video','udemy','lecture'],text:'CodeTrail is a written, interactive course. It uses explanations, worked examples, exercises and quizzes rather than prerecorded video lectures. You can learn at your own pace.'},
{keys:['privacy','data','secure','secrets','delete','personal'],text:'Account progress and code drafts are saved on the hosted service, associated with your account. This homepage chat stays in this tab unless you enable account memory. The coding tutor runs locally after downloading public model files; enabled account memory uploads chat questions and answers. Don’t enter secrets such as API keys. There is currently no self-service account-data deletion control.'},
{keys:['share','public','link','host','close','online','other people','friends'],text:'The homepage is publicly accessible, even when the creator closes the app. Courses and practice require sign-in. Each learner uses their own account for private progress. Community discovery is optional; code rooms require invitations and editing requires owner approval.'},
{keys:['import','old','previous','localstorage','browser only'],text:'After you sign in, the workspace may offer “Import my previous progress” if it finds an older browser-saved copy. Import only if that progress belongs to you. It merges into your account progress rather than silently assigning another person’s work to your account.'},
{keys:['conflict','recover','recovered','multiple devices','overwritten'],text:'Cloud saving checks for updates from another device. Separate changes can be merged; when the same code draft was edited differently, a version can be kept under Recovered code versions. Choose a version to restore. Wait for a successful save before switching devices.'},
{keys:['community','connect','partner','partners','collaborate','chat room','shared','comments','enrollment','register course'],text:'Open Study together and choose a course. Its Learn & practice panel includes concepts, examples, challenges, hints and private quick checks. In a room, the host can set a shared lesson while participants keep their own editors. Join with a community display name and optionally appear in its learner directory. Request and accept study connections, then invite partners into a separate coding room. View-only is the default; owners can grant editing. You see your own editor first. Click a teammate’s name to open their shared editor in split view; each editor’s owner approves edits. Saved code syncs every few seconds. Course comments are shared with enrolled learners; room code and comments stay within the invited group. Your private practice drafts are never automatically shared.'},
{keys:['memory','history','remember'],text:'Account memory is optional and off by default. Open Memory to enable it and set learning preferences. The latest 20 tutor and homepage-guide exchanges are saved privately to your account. Tutor conversations may include code. You can disable saving or clear saved history; never include secrets.'},
{keys:['credits','points','rating','ratings','tasks','achievements','agentic','academy'],text:'The AI academy has detailed courses at beginner, intermediate and advanced levels, including agentic AI. Each lesson has a checkpoint and practical task. A passed checkpoint earns 15 points, a submitted task 25, and a capstone 75. Completing all requirements earns course credits plus a 100-point bonus. Credits are internal learning achievements, not academic accreditation. Task evidence is self-assessed. You can privately rate each course from 1 to 5 stars.'},
{keys:['dashboard','catalog','search','find'],text:'The dashboard shows your saved learning milestones and a link to continue your lesson. The course catalog searches lesson topics and coding exercises, with language, module and challenge-level filters. Use the sidebar to switch between Dashboard, Course catalog, Workspace, Progress and Profile.'},
{keys:['profile','name','goal','preferences','daily'],text:'On Profile, sign in and set your display name, learning goal and daily practice intention. Choose Save profile to store these with your account. These preferences do not change your OpenAI identity. The daily target does not track time or schedule reminders.'},
{keys:['chatbot','guide','you','chat','questions','feature','features','help'],text:'I answer questions using built-in CodeTrail feature information. I’m not a generative AI and can’t see your account or diagnose your code. Ask about the course, Python, Java, login, cloud saves, hints or the coding tutor. For code explanations, open the AI tutor in the workspace.'}
];
function answer(q){const s=q.toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();if(/^(hi|hello|hey|thanks|thank you)$/.test(s))return 'Hi! What would you like to know about CodeTrail? Try “What does the course cover?” or “How is my progress saved?”';if(/\bjava\b/.test(s))return answers[6].text;if(/\b(google|login|log in|sign in|signup|register)\b/.test(s)&&! /\b(save|saved|saving|progress|draft)\b/.test(s))return answers[2].text;const tokens=s.split(' ');const ranked=answers.map((a,i)=>({a,i,score:a.keys.reduce((n,k)=>n+(k.includes(' ')?(s.includes(k)?5:0):(tokens.includes(k)?(k.length>5?3:2):0)),0)})).sort((a,b)=>b.score-a.score);if(!ranked[0].score)return 'I don’t have a verified answer to that in the feature guide. I can help with the course, Python and Java practice, login, cloud saving, hints and the AI tutor. For coding questions, open the workspace tutor. Try asking about one of those features.';return ranked[0].a.text;}
window.CodeTrailGuide={answer};let guideBusy=false;let returnFocus=null,guideMemoryLoaded=false;async function restoreGuide(){if(guideMemoryLoaded)return;guideMemoryLoaded=true;const m=await window.CodeTrailMemory?.load();if(m?.enabled){const log=$('guide-messages');for(const t of m.turns.filter(t=>t.context==='guide').slice(-3)){for(const [type,text]of[['question',t.user],['reply',t.assistant]]){const p=document.createElement('p');p.className=type;p.textContent=text;log.append(p);}}}}function openGuide(){restoreGuide();returnFocus=document.activeElement;$('guide-panel').hidden=false;$('guide-launch').setAttribute('aria-expanded','true');$('guide-question').focus();}function closeGuide(){$('guide-panel').hidden=true;$('guide-launch').setAttribute('aria-expanded','false');returnFocus?.focus();}$('guide-launch').onclick=()=> $('guide-panel').hidden?openGuide():closeGuide();$('open-guide').onclick=openGuide;$('guide-close').onclick=closeGuide;addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('guide-panel').hidden)closeGuide();});async function ask(q){q=q.trim().slice(0,500);if(!q||guideBusy)return;guideBusy=true;const log=$('guide-messages'),send=$('guide-form').querySelector('button');send.disabled=true;const question=document.createElement('p');question.className='question';question.textContent=q;log.append(question);const pending=document.createElement('p');pending.className='reply guide-thinking';pending.setAttribute('aria-busy','true');pending.setAttribute('aria-label','Preparing a feature-guide reply');const dots=document.createElement('span');dots.className='typing-indicator';dots.setAttribute('aria-hidden','true');for(let i=0;i<3;i++){const dot=document.createElement('span');dot.className='typing-dot';dots.append(dot);}pending.append(dots);log.append(pending);log.scrollTop=log.scrollHeight;$('guide-question').value='';let reply='';try{await new Promise(resolve=>setTimeout(resolve,reduced?0:200));reply=answer(q);pending.classList.remove('guide-thinking');pending.removeAttribute('aria-busy');pending.removeAttribute('aria-label');pending.textContent=reply;}catch{pending.textContent='The feature guide could not prepare an answer. Try again.';}finally{pending.classList.remove('guide-thinking');pending.removeAttribute('aria-busy');pending.removeAttribute('aria-label');guideBusy=false;send.disabled=false;while(log.children.length>60)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;}if(!reply)return;await window.CodeTrailMemory?.load();const m=window.CodeTrailMemory?.snapshot();const saved=await window.CodeTrailMemory?.append(m,q,reply,'guide');if(saved?.error){const p=document.createElement('p');p.className='reply';p.textContent='This exchange was not saved to account memory: '+saved.error;log.append(p);}}$('guide-form').onsubmit=e=>{e.preventDefault();ask($('guide-question').value);};document.querySelectorAll('.guide-suggestions button').forEach(b=>b.onclick=()=>ask(b.textContent));$('privacy-open').onclick=()=>$('privacy-dialog').showModal();$('privacy-close').onclick=()=>$('privacy-dialog').close();fetch('/api/progress',{credentials:'same-origin'}).then(r=>{if(r.ok){$('home-login').textContent='CONTINUE LEARNING ↗';$('home-login').href='/learn';}}).catch(()=>{});
})();
